// node --test server/deploy/redeploy-spawn-market.test.mjs
// Pure logic only (bounds parsing, plan shape, log-wait substring matching); never touches the
// panel, same reasoning as kinetic.test.mjs.
import { test } from "node:test";
import assert from "node:assert/strict";
import { buildPlan, localFunctionFiles, parseDefaultBounds, waitForLogText, FUNCTION_DIR } from "./redeploy-spawn-market.mjs";

test("default bounds are parsed from build.mcfunction's own forceload add line", () => {
  const text = [
    "# Generated by server/spawn-market/generate.mjs - do not edit by hand. Entry point.",
    "forceload add 403 -892 451 -844",
    'tellraw @a {"text":"[spawn-market] building in 2s...","color":"gray"}',
    "schedule function spawn_market:build_run 40t",
  ].join("\n");
  assert.deepEqual(parseDefaultBounds(text), { x0: 403, z0: -892, x1: 451, z1: -844 });
});

test("parseDefaultBounds fails loudly when the line is missing", () => {
  assert.throws(() => parseDefaultBounds("no forceload line here"), /forceload add/);
});

test("the real datapack's function dir only has .mcfunction files, none hidden by the filter", () => {
  const files = localFunctionFiles(FUNCTION_DIR);
  assert.ok(files.length >= 5, "expected build/build_run/clear/structure/attach/terrain at least");
  for (const f of files) assert.match(f, /\.mcfunction$/);
  assert.deepEqual(files, [...files].sort(), "listing is sorted for a stable plan");
});

test("the plan uploads every local file, then reload, forceload add, build, forceload remove, in order", () => {
  const bounds = { x0: 1, z0: 2, x1: 3, z1: 4 };
  const plan = buildPlan(["attach.mcfunction", "build.mcfunction"], bounds);
  assert.deepEqual(plan.map((s) => s.kind), ["upload", "upload", "console", "console", "console", "console"]);
  assert.deepEqual(plan.slice(2).map((s) => s.command), [
    "reload confirm",
    "forceload add 1 2 3 4",
    "function spawn_market:build",
    "forceload remove 1 2 3 4",
  ]);
  assert.equal(plan[2].waitFor, "Reloading!");
  assert.equal(plan[4].waitFor, "[spawn-market] done");
  assert.equal(plan[3].waitFor, undefined, "forceload add itself has no completion line to wait for");
});

test("waitForLogText polls until the substring appears in text appended after the baseline", async () => {
  const baseline = "line one\nline two\n";
  const texts = [
    baseline, // first poll: nothing new yet
    baseline, // second poll: still nothing
    `${baseline}[spawn-market] done\n`, // third poll: there it is
  ];
  let call = 0;
  const getLogText = async () => texts[Math.min(call++, texts.length - 1)];
  await waitForLogText("fake-id", baseline, "[spawn-market] done", { pollMs: 0, getLogText });
  assert.equal(call, 3);
});

test("waitForLogText times out loudly if the substring never appears", async () => {
  const baseline = "line one\n";
  const getLogText = async () => baseline; // never grows
  await assert.rejects(
    () => waitForLogText("fake-id", baseline, "never shows up", { pollMs: 0, timeoutMs: 5, getLogText }),
    /timed out after/,
  );
});

test("waitForLogText keeps polling through a transient panel read failure instead of throwing", async () => {
  const baseline = "line one\n";
  let call = 0;
  const getLogText = async () => {
    call++;
    if (call === 1) throw new Error("502 Bad Gateway");
    return `${baseline}[spawn-market] done\n`;
  };
  await waitForLogText("fake-id", baseline, "[spawn-market] done", { pollMs: 0, getLogText });
  assert.equal(call, 2);
});
